// Use-case definitions for the Octoloom example templates. Every agent and MCP server here is a
// fresh A2D mock (see generate.mjs). No credentials: the LLM key is a deploy-time secret variable.
//
// Agent:  { key, name, description, platform, proto: '0.3.0' | '1.0', skills: [...], replies: [[keyword, text], ...], fallback }
// MCP:    { key, name, description, tools: [{ name, description, input: {prop: [type, description]}, required, cases: [[prop, value, json]], fallback }] }

const sk = (id, name, description, examples, tags = []) => ({ id, name, description, examples, tags });
const tool = (name, description, input, cases, fallback, required) => ({ name, description, input, cases, fallback, required: required ?? Object.keys(input).slice(0, 1) });

